// ============================================================================
// Xmamba Monolithic CFU Top Module
// Autogenerated for CFU Playground (LiteX / VexRiscv / Renode / Vivado)
// Modules: mb_mac_unit, mb_xmamba_unit (with inlined tables), Cfu
// ============================================================================

`timescale 1ns / 1ps

// ============================================================================
// 1. MAC UNIT (mb_mac_unit.v)
// ============================================================================
`timescale 1ns / 1ps

// mb_mac_unit: the mb.mac4 and mb.racc instructions of the RISCVMamba/Xmamba CFU.
//
//   function id = {funct7, funct3}; both instructions use funct3 = 0
//     funct7 = 0  mb.mac4 rs1, rs2 : acc += sum_{i=0..3} int8(rs1.lane[i]) * int8(rs2.lane[i])
//                                    lane 0 = bits [7:0] ... lane 3 = bits [31:24]
//                                    response value is 0
//     funct7 = 1  mb.racc rd, rs1  : rd = saturate_OUT_BITS( (acc + 2^(s-1)) >>> s ), s = rs1[4:0]
//                                    (round half up; no rounding term when s = 0), then acc = 0
//     anything else               : responds with 0, state unchanged (never hangs the CPU)
//
// Accumulator: 32-bit two's complement, wraps on overflow (no saturation).
//   One mac4 adds at most 4 * 128 * 128 = 2^16, so overflow needs >= 2^15 mac4 ops.
//
// Timing (CFU handshake, registered response):
//   mb.mac4: accepted on edge A, response visible after A, accumulator updated after A+2.
//   mb.racc: waits until earlier mac4 work has reached the accumulator, then answers.
//   cmd_ready is low while a response is pending or a racc is running.
//
// Reset is synchronous and active high, as in CFU Playground.
module mb_mac_unit #(
    parameter integer OUT_BITS = 8          // racc saturates to a signed OUT_BITS-bit range
)(
    input  wire        clk,
    input  wire        reset,
    input  wire        cmd_valid,
    output wire        cmd_ready,
    input  wire [9:0]  cmd_payload_function_id,
    input  wire [31:0] cmd_payload_inputs_0,
    input  wire [31:0] cmd_payload_inputs_1,
    output wire        rsp_valid,
    input  wire        rsp_ready,
    output wire [31:0] rsp_payload_outputs_0,
    output wire [31:0] dbg_acc              // test/debug view of the accumulator
);
    // ------------------------------------------------------------------ decode
    wire [2:0] funct3 = cmd_payload_function_id[2:0];
    wire [6:0] funct7 = cmd_payload_function_id[9:3];
    wire is_mac4 = (funct3 == 3'd0) && (funct7 == 7'd0);
    wire is_racc = (funct3 == 3'd0) && (funct7 == 7'd1);

    reg        rsp_valid_r;
    reg [31:0] rsp_data_r;
    reg        racc_busy;
    reg [4:0]  racc_shift;

    assign cmd_ready             = ~rsp_valid_r & ~racc_busy;
    assign rsp_valid             = rsp_valid_r;
    assign rsp_payload_outputs_0 = rsp_data_r;

    wire accept = cmd_valid & cmd_ready;

    // ------------------------------------------- datapath (no reset needed)
    // Stage 1: four signed 8x8 products, registered.
    // Stage 2: sum of the four products (18-bit signed), registered.
    // Stage 3: add into the 32-bit accumulator (in the control block below).
    wire signed [7:0] a0 = cmd_payload_inputs_0[7:0];
    wire signed [7:0] a1 = cmd_payload_inputs_0[15:8];
    wire signed [7:0] a2 = cmd_payload_inputs_0[23:16];
    wire signed [7:0] a3 = cmd_payload_inputs_0[31:24];
    wire signed [7:0] b0 = cmd_payload_inputs_1[7:0];
    wire signed [7:0] b1 = cmd_payload_inputs_1[15:8];
    wire signed [7:0] b2 = cmd_payload_inputs_1[23:16];
    wire signed [7:0] b3 = cmd_payload_inputs_1[31:24];

    wire signed [15:0] m0 = a0 * b0;
    wire signed [15:0] m1 = a1 * b1;
    wire signed [15:0] m2 = a2 * b2;
    wire signed [15:0] m3 = a3 * b3;

    reg signed [15:0] prod0, prod1, prod2, prod3;
    reg signed [17:0] psum;

    wire signed [17:0] e0 = {{2{prod0[15]}}, prod0};
    wire signed [17:0] e1 = {{2{prod1[15]}}, prod1};
    wire signed [17:0] e2 = {{2{prod2[15]}}, prod2};
    wire signed [17:0] e3 = {{2{prod3[15]}}, prod3};

    always @(posedge clk) begin
        prod0 <= m0;
        prod1 <= m1;
        prod2 <= m2;
        prod3 <= m3;
        psum  <= e0 + e1 + e2 + e3;
    end

    // ------------------------------------------------- racc: round + saturate
    reg signed [31:0] acc;
    assign dbg_acc = acc;

    localparam signed [32:0] SAT_MAX =  (33'sd1 <<< (OUT_BITS - 1)) - 33'sd1;
    localparam signed [32:0] SAT_MIN = -(33'sd1 <<< (OUT_BITS - 1));

    wire signed [32:0] acc_ext  = {acc[31], acc};
    wire signed [32:0] rnd_add  = (racc_shift == 5'd0) ? 33'sd0
                                  : (33'sd1 <<< (racc_shift - 5'd1));
    wire signed [32:0] biased   = acc_ext + rnd_add;
    wire signed [32:0] shifted  = biased >>> racc_shift;
    wire signed [32:0] sat      = (shifted > SAT_MAX) ? SAT_MAX :
                                  (shifted < SAT_MIN) ? SAT_MIN : shifted;
    wire        [31:0] racc_result = sat[31:0];

    // ----------------------------------------------------------------- control
    reg v1, v2;                          // mac4 work in stage 1 / stage 2
    wire racc_done = racc_busy & ~v1 & ~v2;

    always @(posedge clk) begin
        if (reset) begin
            v1          <= 1'b0;
            v2          <= 1'b0;
            rsp_valid_r <= 1'b0;
            rsp_data_r  <= 32'd0;
            racc_busy   <= 1'b0;
            racc_shift  <= 5'd0;
            acc         <= 32'sd0;
        end else begin
            v1 <= accept & is_mac4;
            v2 <= v1;

            // the CPU took the response
            if (rsp_valid_r & rsp_ready) rsp_valid_r <= 1'b0;

            // a new command (cmd_ready guarantees no response is pending)
            if (accept) begin
                if (is_racc) begin
                    racc_busy  <= 1'b1;
                    racc_shift <= cmd_payload_inputs_0[4:0];
                end else begin
                    rsp_valid_r <= 1'b1;
                    rsp_data_r  <= 32'd0;       // mac4 and unknown ops return 0
                end
            end

            // stage 3: accumulate
            if (v2) acc <= acc + $signed({{14{psum[17]}}, psum});

            // racc: finish once the accumulator is up to date
            if (racc_done) begin
                rsp_data_r  <= racc_result;
                rsp_valid_r <= 1'b1;
                racc_busy   <= 1'b0;
                acc         <= 32'sd0;
            end
        end
    end
endmodule


// ============================================================================
// 2. NONLINEAR & SCAN ENGINE (mb_xmamba_unit.v)
// ============================================================================
`timescale 1ns / 1ps

module mb_xmamba_unit #(
    parameter integer LAYERS = 2,
    parameter integer CHANNELS = 8,
    parameter integer STATES = 4
)(
    input wire clk,
    input wire reset,
    input wire cmd_valid,
    output wire cmd_ready,
    input wire [9:0] cmd_payload_function_id,
    input wire [31:0] cmd_payload_inputs_0,
    input wire [31:0] cmd_payload_inputs_1,
    output reg rsp_valid,
    input wire rsp_ready,
    output reg [31:0] rsp_payload_outputs_0
);
    localparam integer STATE_COUNT = LAYERS * CHANNELS * STATES;
    localparam integer CONST_STRIDE = CHANNELS * STATES + CHANNELS;
    reg signed [31:0] hidden [0:STATE_COUNT-1];
    reg signed [15:0] constants [0:LAYERS*CONST_STRIDE-1];
    reg signed [15:0] coeff_b [0:LAYERS*STATES-1];
    reg signed [15:0] coeff_c [0:LAYERS*STATES-1];
    integer layer_id, channel_id, state_id, clear_index, reset_index, reset_layer;
    reg [2:0] phase;
    reg scanning, clearing;
    reg signed [31:0] delta, activation, decay, injection, output_sum;
    wire [2:0] group_id = cmd_payload_function_id[2:0];
    wire [6:0] operation = cmd_payload_function_id[9:3];
    wire signed [31:0] operand0 = $signed(cmd_payload_inputs_0);
    wire signed [15:0] low_half = $signed(cmd_payload_inputs_0[15:0]);
    wire signed [15:0] high_half = $signed(cmd_payload_inputs_0[31:16]);
    wire signed [15:0] constant_value = constants[layer_id * CONST_STRIDE + channel_id * STATES + state_id];
    wire signed [15:0] skip_value = constants[layer_id * CONST_STRIDE + CHANNELS * STATES + channel_id];
    wire signed [15:0] current_b = coeff_b[layer_id * STATES + state_id];
    wire signed [15:0] current_c = coeff_c[layer_id * STATES + state_id];
    wire signed [31:0] current_hidden = hidden[(layer_id * CHANNELS + channel_id) * STATES + state_id];

    assign cmd_ready = !rsp_valid && !scanning && !clearing;

    // --- BEGIN INLINED xmamba_tables.vh ---
function signed [31:0] exp_table;
  input [5:0] index;
  begin
    case (index)
      6'd0: exp_table = 32'sd256;
      6'd1: exp_table = 32'sd155;
      6'd2: exp_table = 32'sd94;
      6'd3: exp_table = 32'sd57;
      6'd4: exp_table = 32'sd35;
      6'd5: exp_table = 32'sd21;
      6'd6: exp_table = 32'sd13;
      6'd7: exp_table = 32'sd8;
      6'd8: exp_table = 32'sd5;
      6'd9: exp_table = 32'sd3;
      6'd10: exp_table = 32'sd2;
      6'd11: exp_table = 32'sd1;
      6'd12: exp_table = 32'sd1;
      6'd13: exp_table = 32'sd0;
      6'd14: exp_table = 32'sd0;
      6'd15: exp_table = 32'sd0;
      6'd16: exp_table = 32'sd0;
      default: exp_table = 32'sd0;
    endcase
  end
endfunction
function signed [31:0] silu_table;
  input [5:0] index;
  begin
    case (index)
      6'd0: silu_table = -32'sd1;
      6'd1: silu_table = -32'sd1;
      6'd2: silu_table = -32'sd2;
      6'd3: silu_table = -32'sd2;
      6'd4: silu_table = -32'sd4;
      6'd5: silu_table = -32'sd6;
      6'd6: silu_table = -32'sd9;
      6'd7: silu_table = -32'sd13;
      6'd8: silu_table = -32'sd18;
      6'd9: silu_table = -32'sd26;
      6'd10: silu_table = -32'sd36;
      6'd11: silu_table = -32'sd49;
      6'd12: silu_table = -32'sd61;
      6'd13: silu_table = -32'sd70;
      6'd14: silu_table = -32'sd69;
      6'd15: silu_table = -32'sd48;
      6'd16: silu_table = 32'sd0;
      6'd17: silu_table = 32'sd80;
      6'd18: silu_table = 32'sd187;
      6'd19: silu_table = 32'sd314;
      6'd20: silu_table = 32'sd451;
      6'd21: silu_table = 32'sd591;
      6'd22: silu_table = 32'sd732;
      6'd23: silu_table = 32'sd870;
      6'd24: silu_table = 32'sd1006;
      6'd25: silu_table = 32'sd1139;
      6'd26: silu_table = 32'sd1271;
      6'd27: silu_table = 32'sd1402;
      6'd28: silu_table = 32'sd1532;
      6'd29: silu_table = 32'sd1662;
      6'd30: silu_table = 32'sd1790;
      6'd31: silu_table = 32'sd1919;
      6'd32: silu_table = 32'sd2047;
      default: silu_table = 32'sd0;
    endcase
  end
endfunction
function signed [31:0] softplus_table;
  input [5:0] index;
  begin
    case (index)
      6'd0: softplus_table = 32'sd0;
      6'd1: softplus_table = 32'sd0;
      6'd2: softplus_table = 32'sd0;
      6'd3: softplus_table = 32'sd0;
      6'd4: softplus_table = 32'sd1;
      6'd5: softplus_table = 32'sd1;
      6'd6: softplus_table = 32'sd2;
      6'd7: softplus_table = 32'sd3;
      6'd8: softplus_table = 32'sd5;
      6'd9: softplus_table = 32'sd8;
      6'd10: softplus_table = 32'sd12;
      6'd11: softplus_table = 32'sd20;
      6'd12: softplus_table = 32'sd32;
      6'd13: softplus_table = 32'sd52;
      6'd14: softplus_table = 32'sd80;
      6'd15: softplus_table = 32'sd121;
      6'd16: softplus_table = 32'sd177;
      6'd17: softplus_table = 32'sd249;
      6'd18: softplus_table = 32'sd336;
      6'd19: softplus_table = 32'sd436;
      6'd20: softplus_table = 32'sd544;
      6'd21: softplus_table = 32'sd660;
      6'd22: softplus_table = 32'sd780;
      6'd23: softplus_table = 32'sd904;
      6'd24: softplus_table = 32'sd1029;
      6'd25: softplus_table = 32'sd1155;
      6'd26: softplus_table = 32'sd1282;
      6'd27: softplus_table = 32'sd1409;
      6'd28: softplus_table = 32'sd1537;
      6'd29: softplus_table = 32'sd1664;
      6'd30: softplus_table = 32'sd1792;
      6'd31: softplus_table = 32'sd1920;
      6'd32: softplus_table = 32'sd2048;
      default: softplus_table = 32'sd0;
    endcase
  end
endfunction

// --- END INLINED xmamba_tables.vh ---

    function signed [31:0] saturate;
        input signed [63:0] value;
        begin
            if (value > 64'sd2147483647) saturate = 32'sh7fffffff;
            else if (value < -64'sd2147483648) saturate = 32'sh80000000;
            else saturate = value[31:0];
        end
    endfunction

    function signed [31:0] qmul;
        input signed [31:0] left_value, right_value;
        reg signed [63:0] product;
        begin
            product = left_value * right_value;
            qmul = saturate(product >>> 8);
        end
    endfunction

    function signed [31:0] qadd;
        input signed [31:0] left_value, right_value;
        begin
            qadd = saturate({{32{left_value[31]}}, left_value} + {{32{right_value[31]}}, right_value});
        end
    endfunction

    function signed [31:0] nonlinear;
        input [6:0] kind;
        input signed [31:0] value;
        reg signed [31:0] position, fraction, lower_value, upper_value;
        reg [5:0] table_index;
        begin
            if (kind == 0 && value >= 0) nonlinear = 32'sd256;
            else if (value <= -2048) nonlinear = 0;
            else if (kind != 0 && value >= 2048) nonlinear = value;
            else begin
                position = (kind == 0) ? -value : value + 2048;
                table_index = position[12:7];
                fraction = {25'd0, position[6:0]};
                case (kind)
                    0: begin lower_value = exp_table(table_index); upper_value = exp_table(table_index + 6'd1); end
                    1: begin lower_value = silu_table(table_index); upper_value = silu_table(table_index + 6'd1); end
                    default: begin lower_value = softplus_table(table_index); upper_value = softplus_table(table_index + 6'd1); end
                endcase
                nonlinear = lower_value + (((upper_value - lower_value) * fraction) >>> 7);
            end
        end
    endfunction

    always @(posedge clk) begin
        if (reset) begin
            rsp_valid <= 0;
            rsp_payload_outputs_0 <= 0;
            scanning <= 0;
            clearing <= 0;
            layer_id <= 0;
            channel_id <= 0;
            state_id <= 0;
            clear_index <= 0;
            phase <= 0;
            delta <= 0;
            activation <= 0;
            decay <= 0;
            injection <= 0;
            output_sum <= 0;
            for (reset_index = 0; reset_index < STATE_COUNT; reset_index = reset_index + 1)
                hidden[reset_index] <= 0;
            for (reset_layer = 0; reset_layer < LAYERS; reset_layer = reset_layer + 1)
                for (reset_index = 0; reset_index < CONST_STRIDE; reset_index = reset_index + 1)
                    constants[reset_layer * CONST_STRIDE + reset_index] <= 0;
            for (reset_index = 0; reset_index < LAYERS * STATES; reset_index = reset_index + 1) begin
                coeff_b[reset_index] <= 0;
                coeff_c[reset_index] <= 0;
            end
        end else begin
            if (rsp_valid && rsp_ready) rsp_valid <= 0;
            if (cmd_valid && cmd_ready) begin
                rsp_payload_outputs_0 <= 0;
                rsp_valid <= 1;
                if (group_id == 1 && operation < 3)
                    rsp_payload_outputs_0 <= nonlinear(operation, operand0);
                else if (group_id == 2) begin
                    case (operation)
                        0: if (cmd_payload_inputs_0 < CONST_STRIDE)
                            constants[layer_id * CONST_STRIDE + cmd_payload_inputs_0] <= cmd_payload_inputs_1[15:0];
                        1: if (cmd_payload_inputs_0 < LAYERS) layer_id <= cmd_payload_inputs_0;
                        2: if (cmd_payload_inputs_0 < STATES) begin
                            coeff_b[layer_id * STATES + cmd_payload_inputs_0] <= cmd_payload_inputs_1[15:0];
                            coeff_c[layer_id * STATES + cmd_payload_inputs_0] <= cmd_payload_inputs_1[31:16];
                        end
                        3: if (cmd_payload_inputs_1 < CHANNELS) begin
                            channel_id <= cmd_payload_inputs_1;
                            delta <= {{16{low_half[15]}}, low_half};
                            activation <= {{16{high_half[15]}}, high_half};
                            state_id <= 0;
                            output_sum <= 0;
                            phase <= 0;
                            scanning <= 1;
                            rsp_valid <= 0;
                        end
                        4: begin clearing <= 1; clear_index <= 0; rsp_valid <= 0; end
                        default: begin end
                    endcase
                end
            end
            if (clearing) begin
                hidden[clear_index] <= 0;
                if (clear_index == STATE_COUNT - 1) begin
                    clearing <= 0;
                    rsp_valid <= 1;
                    rsp_payload_outputs_0 <= 0;
                end else clear_index <= clear_index + 1;
            end
            if (scanning) begin
                case (phase)
                    0: begin
                        decay <= nonlinear(0, qmul(delta, {{16{constant_value[15]}}, constant_value}));
                        injection <= qmul(qmul(delta, {{16{current_b[15]}}, current_b}), activation);
                        phase <= 1;
                    end
                    1: begin
                        hidden[(layer_id * CHANNELS + channel_id) * STATES + state_id] <=
                            qadd(qmul(decay, current_hidden), injection);
                        phase <= 2;
                    end
                    2: begin
                        output_sum <= qadd(output_sum, qmul({{16{current_c[15]}}, current_c}, current_hidden));
                        if (state_id == STATES - 1) phase <= 3;
                        else begin state_id <= state_id + 1; phase <= 0; end
                    end
                    default: begin
                        rsp_payload_outputs_0 <= qadd(output_sum, qmul({{16{skip_value[15]}}, skip_value}, activation));
                        scanning <= 0;
                        rsp_valid <= 1;
                    end
                endcase
            end
        end
    end
endmodule

// ============================================================================
// 3. CFU TOP ROUTING (cfu_top.v)
// ============================================================================
`timescale 1ns / 1ps

module Cfu (
  input               cmd_valid,
  output              cmd_ready,
  input      [9:0]    cmd_payload_function_id,
  input      [31:0]   cmd_payload_inputs_0,
  input      [31:0]   cmd_payload_inputs_1,
  output              rsp_valid,
  input               rsp_ready,
  output     [31:0]   rsp_payload_outputs_0,
  input               reset,
  input               clk
);
  wire select_mac = cmd_payload_function_id[2:0] == 0;
  wire mac_ready, mac_valid, xm_ready, xm_valid;
  wire [31:0] mac_result, xm_result;
  reg pending, active_mac;
  assign cmd_ready = !pending && (select_mac ? mac_ready : xm_ready);
  assign rsp_valid = pending && (active_mac ? mac_valid : xm_valid);
  assign rsp_payload_outputs_0 = active_mac ? mac_result : xm_result;

  always @(posedge clk) begin
    if (reset) begin
      pending <= 0;
      active_mac <= 0;
    end else begin
      if (cmd_valid && cmd_ready) begin
        pending <= 1;
        active_mac <= select_mac;
      end
      if (rsp_valid && rsp_ready) pending <= 0;
    end
  end

  mb_mac_unit #(.OUT_BITS(8)) u_mac (
    .clk(clk), .reset(reset),
    .cmd_valid(cmd_valid && !pending && select_mac), .cmd_ready(mac_ready),
    .cmd_payload_function_id(cmd_payload_function_id),
    .cmd_payload_inputs_0(cmd_payload_inputs_0),
    .cmd_payload_inputs_1(cmd_payload_inputs_1),
    .rsp_valid(mac_valid), .rsp_ready(rsp_ready && pending && active_mac),
    .rsp_payload_outputs_0(mac_result),
    .dbg_acc()
  );

  mb_xmamba_unit u_xmamba (
    .clk(clk), .reset(reset),
    .cmd_valid(cmd_valid && !pending && !select_mac), .cmd_ready(xm_ready),
    .cmd_payload_function_id(cmd_payload_function_id),
    .cmd_payload_inputs_0(cmd_payload_inputs_0),
    .cmd_payload_inputs_1(cmd_payload_inputs_1),
    .rsp_valid(xm_valid), .rsp_ready(rsp_ready && pending && !active_mac),
    .rsp_payload_outputs_0(xm_result)
  );
endmodule

